mapper.select:
select subject_id as subjectId, subject_code as subjectCode, subject_name as subjectName, subject_type as subjectType, balance_direction as balanceDirection, status, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from fin_account_subject
and status = #{status}
order by subject_code asc

select count(1)
from fin_account_subject
where subject_code = #{subjectCode}

  and subject_id != #{excludeId}

mapper.insert:
insert into fin_account_subject (
    subject_code, subject_name, subject_type, balance_direction, status,
    create_by, create_time, remark
) values (
    #{subjectCode}, #{subjectName}, coalesce(#{subjectType}, 'asset'),
    coalesce(#{balanceDirection}, 'debit'), coalesce(#{status}, '0'),
    coalesce(#{createBy}, 'admin'), sysdate(), #{remark}
)

mapper.update:
update fin_account_subject
subject_code = #{subjectCode}, subject_name = #{subjectName}, subject_type = #{subjectType}, balance_direction = #{balanceDirection}, status = #{status}, remark = #{remark}, update_by = coalesce(#{updateBy}, 'admin'), update_time = sysdate()
where subject_id = #{subjectId}

mapper.select:
select auxiliary_id as auxiliaryId, auxiliary_type as auxiliaryType, item_code as itemCode, item_name as itemName, relation_id as relationId, status, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from fin_auxiliary_item
and auxiliary_type = #{auxiliaryType}
order by auxiliary_type asc, item_code asc

select count(1)
from fin_auxiliary_item
where auxiliary_type = #{auxiliaryType}
  and relation_id = #{relationId}

mapper.insert:
insert into fin_auxiliary_item (
    auxiliary_type, item_code, item_name, relation_id, status, create_by, create_time, remark
) values (
    #{auxiliaryType}, #{itemCode}, #{itemName}, #{relationId}, coalesce(#{status}, '0'),
    coalesce(#{operator}, 'admin'), sysdate(), '主数据自动同步'
)

mapper.select:
select period_id as periodId, period_code as periodCode, start_date as startDate, end_date as endDate, close_status as closeStatus, close_by as closeBy, close_time as closeTime, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from fin_fiscal_period
and close_status = #{closeStatus}
order by period_code desc

mapper.insert:
insert into fin_fiscal_period (
    period_code, start_date, end_date, close_status, create_by, create_time, remark
) values (
    #{periodCode}, #{startDate}, #{endDate}, 'open', coalesce(#{operator}, 'admin'), sysdate(), #{remark}
)
